static REQUEST_SEQ: AtomicU64 = AtomicU64::new(0);

/// A process-unique id: time where there is a clock, plus a sequence number.
pub fn next_id(prefix: &str) -> String {
    let nanos = wall_clock()
        .and_then(|t| t.duration_since(UNIX_EPOCH).ok())
        .map(|d| d.as_nanos())
        .unwrap_or(0);
    let seq = REQUEST_SEQ.fetch_add(1, Ordering::Relaxed);
    format!("{}{:x}-{:x}", prefix, nanos, seq)
}

/// `SystemTime` as ISO-8601 UTC with milliseconds — what `Date.toJSON()`
/// produces, so a timestamp reads the same from every lane.
pub fn iso8601(time: SystemTime) -> String {
    let d = time.duration_since(UNIX_EPOCH).unwrap_or_default();
    let secs = d.as_secs() as i64;
    let (days, rem) = (secs.div_euclid(86_400), secs.rem_euclid(86_400));
    // Days since 1970-01-01 to a civil date (Howard Hinnant's algorithm).
    let z = days + 719_468;
    let era = z.div_euclid(146_097);
    let doe = z - era * 146_097;
    let yoe = (doe - doe / 1_460 + doe / 36_524 - doe / 146_096) / 365;
    let doy = doe - (365 * yoe + yoe / 4 - yoe / 100);
    let mp = (5 * doy + 2) / 153;
    let day = doy - (153 * mp + 2) / 5 + 1;
    let month = if mp < 10 { mp + 3 } else { mp - 9 };
    let year = yoe + era * 400 + i64::from(month <= 2);
    format!(
        "{:04}-{:02}-{:02}T{:02}:{:02}:{:02}.{:03}Z",
        year,
        month,
        day,
        rem / 3_600,
        (rem % 3_600) / 60,
        rem % 60,
        d.subsec_millis()
    )
}

/// Now, as ISO-8601 — `None` where there is no clock.
pub fn iso_now() -> Option<String> {
    wall_clock().map(iso8601)
}

/// Wall-clock time, where the target has a clock.
///
/// `SystemTime::now()` PANICS on `wasm32-unknown-unknown`, which has no clock
/// std can reach (ADR-100). `None` there rather than a fabricated timestamp.
pub fn wall_clock() -> Option<SystemTime> {
    #[cfg(target_arch = "wasm32")]
    {
        None
    }
    #[cfg(not(target_arch = "wasm32"))]
    {
        Some(SystemTime::now())
    }
}

impl MfeContext {
    /// A context with a fresh request id and nothing else.
    pub fn new() -> Self {
        MfeContext {
            request_id: next_id(""),
            capability_id: None,
            inputs: Map::new(),
            jwt: None,
            headers: BTreeMap::new(),
            phase: None,
            capability: None,
            error: None,
        }
    }

    pub fn with_capability_id(mut self, capability_id: impl Into<String>) -> Self {
        self.capability_id = Some(capability_id.into());
        self
    }

    pub fn with_input(mut self, key: impl Into<String>, value: impl Into<Value>) -> Self {
        self.inputs.insert(key.into(), value.into());
        self
    }

    pub fn with_jwt(mut self, jwt: impl Into<String>) -> Self {
        self.jwt = Some(jwt.into());
        self
    }

    pub fn with_header(mut self, name: impl Into<String>, value: impl Into<String>) -> Self {
        self.headers.insert(name.into(), value.into());
        self
    }
}

impl Default for MfeContext {
    fn default() -> Self {
        MfeContext::new()
    }
}

/// One entry in the transition history.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct StateTransition {
    pub from: MfeLifecycleState,
    pub to: MfeLifecycleState,
    /// `None` on targets with no clock (`wasm32-unknown-unknown`).
    pub at: Option<SystemTime>,
}

/// Lock a mutex, recovering the data if a panicking thread poisoned it. The
/// state machine's invariants are enforced by `transition`, not by the lock.
fn lock<T>(m: &Mutex<T>) -> MutexGuard<'_, T> {
    m.lock().unwrap_or_else(|poisoned| poisoned.into_inner())
}

/// Pops the re-entrancy stack when a phase finishes, however it finishes.
struct StackGuard<'a> {
    stack: &'a Mutex<Vec<String>>,
}

impl Drop for StackGuard<'_> {
    fn drop(&mut self) {
        lock(self.stack).pop();
    }
}

/// State, identity, dependencies and the hook engine — everything `BaseMFE`
/// owns that is not a capability entry point.
///
/// Hooks receive `&MfeCore` so they can read state and identity. They cannot
/// run a capability through it: the pipeline is private to this module.
pub struct MfeCore {
    state: Mutex<MfeLifecycleState>,
    history: Mutex<Vec<StateTransition>>,
    identity: MfeIdentity,
    deps: MfeDependencies,
    /// ADR-001's re-entrancy guard, keyed by capability+phase.
    lifecycle_stack: Mutex<Vec<String>>,
}

impl MfeCore {
    pub fn new(identity: MfeIdentity, deps: MfeDependencies) -> Self {
        MfeCore {
            state: Mutex::new(MfeLifecycleState::Uninitialized),
            history: Mutex::new(Vec::new()),
            identity,
            deps,
            lifecycle_stack: Mutex::new(Vec::new()),
        }
    }

    /// Current lifecycle state. Changed only through `transition`.
    pub fn state(&self) -> MfeLifecycleState {
        *lock(&self.state)
    }

    /// Transition history, for the same diagnostic reason `BaseMFE` keeps one.
    pub fn state_history(&self) -> Vec<StateTransition> {
        lock(&self.history).clone()
    }

    pub fn identity(&self) -> &MfeIdentity {
        &self.identity
    }

    pub fn deps(&self) -> &MfeDependencies {
        &self.deps
    }

    /// Fail unless the MFE is in one of the capability's pre-states.
    pub fn assert_state(&self, capability: MfeCapability, context: Option<&MfeContext>) -> Result<(), MfeError> {
        let allowed = capability.pre_states();
        let current = self.state();
        // An empty pre-state list means "any state, including destroyed" —
        // only `emit` is that permissive; telemetry must survive teardown.
        if allowed.is_empty() || allowed.contains(&current) {
            return Ok(());
        }
        let error = MfeError::InvalidState { from: current, attempted: capability, allowed: allowed.to_vec() };
        if let Some(handler) = &self.deps.error_handler {
            let fallback = MfeContext::new().with_capability_id(capability.as_str());
            handler.handle(&error, context.unwrap_or(&fallback));
        }
        Err(error)
    }

    /// Move the state machine along one edge of the transition table.
    pub fn transition(&self, to: MfeLifecycleState, capability: MfeCapability) -> Result<(), MfeError> {
        let mut state = lock(&self.state);
        let from = *state;
        if !from.can_transition_to(to) {
            drop(state);
            let error = MfeError::InvalidState { from, attempted: capability, allowed: from.transitions().to_vec() };
            if let Some(handler) = &self.deps.error_handler {
                handler.handle(&error, &MfeContext::new());
            }
            return Err(error);
        }
        *state = to;
        drop(state);
        lock(&self.history).push(StateTransition { from, to, at: wall_clock() });
        Ok(())
    }

    // ---- The capability pipeline (ADR-098 §1)

    /// The capability pipeline, in the order `BaseMFE.executeCapability`
    /// composes it:
    ///
    /// 1. stateGuard(preStates)
    /// 2. stateTransition(enterState)
    /// 3. errorBoundary(capability, errorState) — wraps 4 to 8
    /// 4. lifecyclePhase(before)
    /// 5. lifecyclePhase(main)
    /// 6. the `do_*` hook
    /// 7. lifecyclePhase(after)
    /// 8. stateTransition(exitState)
    ///
    /// Written as eight steps in sequence rather than a composed middleware
    /// list: async closures that borrow across `.await` do not compose in Rust
    /// without boxing every step, and the order — which is the contract — reads
    /// the same either way. The error boundary sits AFTER the guard and the
    /// enter-transition on purpose: an invalid-state or invalid-transition
    /// error propagates without running the error phase or the error state.
    async fn execute<T, F, Fut>(&self, capability: MfeCapability, context: MfeContext, body: F) -> Result<T, MfeError>
    where
        F: FnOnce(MfeContext) -> Fut,
        Fut: Future<Output = Result<T, MfeError>>,
    {
        let mut context = context;
        context.capability = Some(capability.as_str().to_string());

        // 1.
        self.assert_state(capability, Some(&context))?;
        // 2.
        if let Some(enter) = capability.enter_state() {
            self.transition(enter, capability)?;
        }
        // 3.
        match self.guarded(capability, &mut context, body).await {
            Ok(value) => Ok(value),
            Err(error) => {
                let mut error_context = context.clone();
                error_context.error = Some(error.clone());
                let _ = self.execute_lifecycle(capability, MfeLifecyclePhase::Error, &mut error_context).await;
                if let Some(error_state) = capability.error_state() {
                    if self.state() != error_state {
                        let _ = self.transition(error_state, capability);
                    }
                }
                Err(error)
            }
        }
    }

    /// Steps 4 to 8 — everything the error boundary wraps.
    async fn guarded<T, F, Fut>(&self, capability: MfeCapability, context: &mut MfeContext, body: F) -> Result<T, MfeError>
    where
        F: FnOnce(MfeContext) -> Fut,
        Fut: Future<Output = Result<T, MfeError>>,
    {
        // 4.
        self.execute_lifecycle(capability, MfeLifecyclePhase::Before, context).await?;
        // 5.
        self.execute_lifecycle(capability, MfeLifecyclePhase::Main, context).await?;
        // 6.
        let mut body_context = context.clone();
        body_context.phase = None;
        let value = body(body_context).await?;
        // 7.
        self.execute_lifecycle(capability, MfeLifecyclePhase::After, context).await?;
        // 8.
        if let Some(exit) = capability.exit_state() {
            self.transition(exit, capability)?;
        }
        Ok(value)
    }

    // ---- The hook engine (ADR-002, rendered — ADR-098 §2)

    /// Run every hook the manifest declares for one capability phase.
    ///
    /// Skips rather than fails on re-entrancy (ADR-001): the re-entrant call
    /// is the bug, but the outer call is usually work a user is waiting on.
    async fn execute_lifecycle(
        &self,
        capability: MfeCapability,
        phase: MfeLifecyclePhase,
        context: &mut MfeContext,
    ) -> Result<(), MfeError> {
        let hooks = Self::find_capability_hooks(capability.as_str(), phase);
        if hooks.is_empty() {
            return Ok(());
        }

        let key = format!("{}:{}", capability.as_str(), phase.as_str());
        {
            let mut stack = lock(&self.lifecycle_stack);
            if stack.contains(&key) {
                return Ok(());
            }
            stack.push(key);
        }
        let _guard = StackGuard { stack: &self.lifecycle_stack };

        context.phase = Some(phase);
        context.capability = Some(capability.as_str().to_string());

        for hook in hooks {
            self.execute_hook(hook, context, phase).await?;
        }
        Ok(())
    }

    /// The manifest's hooks for one capability+phase.
    ///
    /// CASE-INSENSITIVE: `MfeCapability::Load.as_str()` is "load", the
    /// manifest writes "Load", and `BaseMFE.findCapabilityConfig` lowercases
    /// both sides. The Swift lane compared exactly at first and every manifest
    /// hook was inert (ADR-098 §Boundaries).
    fn find_capability_hooks(capability: &str, phase: MfeLifecyclePhase) -> Vec<&'static MfeHookSpec> {
        manifest_metadata::HOOKS
            .iter()
            .filter(|h| h.capability.eq_ignore_ascii_case(capability) && h.phase == phase)
            .collect()
    }

    /// One hook's handlers, in order (REQ-045).
    ///
    /// `contained` reports and swallows (REQ-042). A main-phase failure
    /// propagates; before/after/error continue to the next handler (REQ-042,
    /// REQ-045). Every failure reports (REQ-043).
    async fn execute_hook(&self, hook: &MfeHookSpec, context: &MfeContext, phase: MfeLifecyclePhase) -> Result<(), MfeError> {
        for name in hook.handlers {
            if let Err(error) = self.invoke_handler(name, context).await {
                if hook.contained {
                    self.emit_hook_failure(hook.hook, name, &error, context, "warn");
                    continue;
                }
                let severity = if phase == MfeLifecyclePhase::Main { "error" } else { "warn" };
                self.emit_hook_failure(hook.hook, name, &error, context, severity);
                if phase == MfeLifecyclePhase::Main {
                    return Err(error);
                }
            }
        }
        Ok(())
    }

    /// Resolve and run one handler — THE substitution seam, and the only one.
    ///
    /// ADR-079 deleted `deps.lifecycleExecutor` because a seam around the phase
    /// loop skipped containment, propagation and telemetry. Consulting the maps
    /// here means a substituted handler still runs under every guarantee above.
    /// Resolution is the Swift lane's (ADR-098 §3): the handler map is the
    /// mechanism, because Rust cannot look a method up by name either.
    async fn invoke_handler(&self, name: &str, context: &MfeContext) -> Result<(), MfeError> {
        if let Some(platform_name) = name.strip_prefix("platform.") {
            let handler = self.deps.platform_handlers.get(platform_name).ok_or_else(|| MfeError::HandlerNotFound {
                handler: name.to_string(),
                hint: format!(
                    "There is no native platform handler library. Supply it as deps.platform_handlers[\"{}\"].",
                    platform_name
                ),
            })?;
            return handler(context.clone()).await;
        }

        if let Some(handler) = self.deps.custom_handlers.get(name) {
            return handler(context.clone()).await;
        }
        // By last segment, as TypeScript does: 'custom.fail' -> 'fail'.
        let last_segment = name.rsplit('.').next().unwrap_or(name);
        if let Some(handler) = self.deps.custom_handlers.get(last_segment) {
            return handler(context.clone()).await;
        }
        Err(MfeError::HandlerNotFound {
            handler: name.to_string(),
            hint: format!(
                "Register it as deps.custom_handlers[\"{}\"]. Rust cannot resolve a handler to a method by name, so a manifest hook needs the map entry.",
                last_segment
            ),
        })
    }

    /// Report a hook failure (REQ-043), in the shape `BaseMFE` emits it.
    /// Silent until a host supplies telemetry.
    fn emit_hook_failure(&self, hook: &str, handler: &str, error: &MfeError, context: &MfeContext, severity: &str) {
        let mut metadata = Map::new();
        metadata.insert("source".to_string(), Value::from("lifecycle-hook"));
        metadata.insert("hook".to_string(), Value::from(hook));
        metadata.insert("handler".to_string(), Value::from(handler));
        metadata.insert("capability".to_string(), Value::from(context.capability.clone()));
        metadata.insert("mfe".to_string(), Value::from(self.identity.name.clone()));
        metadata.insert("severity".to_string(), Value::from(severity));
        metadata.insert("tags".to_string(), serde_json::json!(["lifecycle", "hook-failure"]));
        metadata.insert("error".to_string(), serde_json::json!({ "message": error.to_string() }));
        self.emit_telemetry("lifecycle-error", "lifecycle", context.phase.map(|p| p.as_str()).unwrap_or("unknown"), "error", metadata);
    }

    /// Emit one event through `deps.telemetry`, if there is one. The
    /// counterpart of `BaseRemoteMFE.emitTelemetry`.
    pub fn emit_telemetry(&self, name: &str, capability: &str, phase: &str, status: &str, metadata: Map<String, Value>) {
        if let Some(telemetry) = &self.deps.telemetry {
            telemetry.emit(MfeTelemetryEvent {
                name: name.to_string(),
                capability: capability.to_string(),
                phase: phase.to_string(),
                user: None,
                duration: None,
                status: status.to_string(),
                metadata,
                timestamp: iso_now(),
            });
        }
    }
}

/// The `do*()` hooks — `protected abstract` in TypeScript.
///
/// Every hook but `do_query` is required. `do_query` has a working default, at
/// the layer TypeScript puts it: `BaseMFE.doQuery` is the one hook that is not
/// abstract (ADR-053, ADR-070).
pub trait MfeHooks: MaybeSendSync {
    fn do_describe<'a>(&'a self, core: &'a MfeCore, context: &'a MfeContext) -> BoxFuture<'a, Result<DescribeResult, MfeError>>;
    fn do_load<'a>(&'a self, core: &'a MfeCore, context: &'a MfeContext) -> BoxFuture<'a, Result<LoadResult, MfeError>>;
    fn do_render<'a>(&'a self, core: &'a MfeCore, context: &'a MfeContext) -> BoxFuture<'a, Result<RenderResult, MfeError>>;
    fn do_refresh<'a>(&'a self, core: &'a MfeCore, context: &'a MfeContext) -> BoxFuture<'a, Result<(), MfeError>>;
    fn do_emit<'a>(&'a self, core: &'a MfeCore, context: &'a MfeContext) -> BoxFuture<'a, Result<EmitResult, MfeError>>;
    fn do_schema<'a>(&'a self, core: &'a MfeCore, context: &'a MfeContext) -> BoxFuture<'a, Result<SchemaResult, MfeError>>;
    fn do_authorize_access<'a>(&'a self, core: &'a MfeCore, context: &'a MfeContext) -> BoxFuture<'a, Result<bool, MfeError>>;
    fn do_health<'a>(&'a self, core: &'a MfeCore, context: &'a MfeContext) -> BoxFuture<'a, Result<HealthResult, MfeError>>;
    fn do_update_control_plane_state<'a>(&'a self, core: &'a MfeCore, context: &'a MfeContext) -> BoxFuture<'a, Result<ControlPlaneStateResult, MfeError>>;

    fn do_query<'a>(&'a self, core: &'a MfeCore, context: &'a MfeContext) -> BoxFuture<'a, Result<QueryResult, MfeError>> {
        Box::pin(default_do_query(core, context))
    }
}

/// Run a GraphQL document against this MFE's BFF.
///
/// Endpoint resolution, in the order ADR-053 fixes, as the Swift lane renders
/// it (ADR-096 §7):
///
/// 1. `context.inputs["bffUrl"]`
/// 2. the `BFF_URL` environment variable
/// 3. `identity.bff_endpoint` — the manifest's, baked at generation
///
/// An MFE with no endpoint answers `data: None` rather than dialing nothing,
/// which is what makes the capability uniform across every MFE (ADR-070).
pub async fn default_do_query(core: &MfeCore, context: &MfeContext) -> Result<QueryResult, MfeError> {
    let target = context
        .inputs
        .get("bffUrl")
        .and_then(Value::as_str)
        .map(str::to_string)
        .or_else(|| std::env::var("BFF_URL").ok())
        .or_else(|| core.identity().bff_endpoint.clone())
        .filter(|t| !t.is_empty());
    let Some(target) = target else {
        return Ok(QueryResult { data: None, errors: Vec::new() });
    };
    let Some(document) = context.inputs.get("document").and_then(Value::as_str) else {
        return Ok(QueryResult {
            data: None,
            errors: vec![QueryError::new("context.inputs[\"document\"] is required for the query capability")],
        });
    };

    let mut headers = context.headers.clone();
    if let Some(jwt) = &context.jwt {
        headers.insert("Authorization".to_string(), format!("Bearer {}", jwt));
    }

    let mut payload = Map::new();
    payload.insert("query".to_string(), Value::String(document.to_string()));
    if let Some(variables) = context.inputs.get("variables") {
        payload.insert("variables".to_string(), variables.clone());
    }
    let request = serde_json::to_vec(&Value::Object(payload)).map_err(|e| MfeError::Decode { message: e.to_string() })?;

    let body = match GraphQlPost::send(core.deps().transport.as_deref(), &target, request, &headers).await {
        Ok(body) => body,
        // The envelope policy: `query` answers with errors, it does not fail.
        // `BffClient::query` fails on the same input — the deliberate half of
        // the difference between the two.
        Err(error) => return Ok(QueryResult { data: None, errors: vec![QueryError::new(error.to_string())] }),
    };

    let decoded: Value = serde_json::from_slice(&body).map_err(|e| MfeError::Decode { message: e.to_string() })?;
    let errors = graphql_errors(&decoded);
    // Partial responses carry both, and the capability returns both.
    let data = decoded.get("data").filter(|d| !d.is_null()).cloned();
    Ok(QueryResult { data, errors })
}

/// Every entry in a GraphQL response's `errors` array, with its path.
pub fn graphql_errors(response: &Value) -> Vec<QueryError> {
    response
        .get("errors")
        .and_then(Value::as_array)
        .map(|list| {
            list.iter()
                .filter_map(|e| {
                    let message = e.get("message").and_then(Value::as_str)?.to_string();
                    let path = e.get("path").and_then(Value::as_array).map(|p| {
                        p.iter()
                            .map(|seg| seg.as_str().map(str::to_string).unwrap_or_else(|| seg.to_string()))
                            .collect()
                    });
                    Some(QueryError { message, path })
                })
                .collect()
        })
        .unwrap_or_default()
}

/// The `message` of every entry in a GraphQL response's `errors` array.
pub fn graphql_error_messages(response: &Value) -> Vec<String> {
    response
        .get("errors")
        .and_then(Value::as_array)
        .map(|list| {
            list.iter()
                .filter_map(|e| e.get("message").and_then(Value::as_str).map(str::to_string))
                .collect()
        })
        .unwrap_or_default()
}

/// The platform contract's ten capabilities over a set of hooks.
///
/// `MfeBase<H>` is the capability surface; `H` supplies the `do_*` hooks. The
/// generated concrete type is `MfeBase<…Native>`, aliased in
/// `generated_mfe.rs`.
pub struct MfeBase<H: MfeHooks> {
    core: MfeCore,
    hooks: H,
}

impl<H: MfeHooks> MfeBase<H> {
    pub fn from_parts(hooks: H, identity: MfeIdentity, deps: MfeDependencies) -> Self {
        MfeBase { core: MfeCore::new(identity, deps), hooks }
    }

    /// Current lifecycle state.
    pub fn state(&self) -> MfeLifecycleState {
        self.core.state()
    }

    pub fn core(&self) -> &MfeCore {
        &self.core
    }

    pub fn hooks(&self) -> &H {
        &self.hooks
    }

    // ---- The ten capabilities

    /// Self-registration — returns the MFE manifest and capabilities.
    pub async fn describe(&self, context: MfeContext) -> Result<DescribeResult, MfeError> {
        self.core
            .execute(MfeCapability::Describe, context, |ctx| async move { self.hooks.do_describe(&self.core, &ctx).await })
            .await
    }

    /// Initialization — connect, warm caches, validate config.
    pub async fn load(&self, context: MfeContext) -> Result<LoadResult, MfeError> {
        self.core
            .execute(MfeCapability::Load, context, |ctx| async move { self.hooks.do_load(&self.core, &ctx).await })
            .await
    }

    /// The MFE produces its own experience for a resolved capability.
    pub async fn render(&self, context: MfeContext) -> Result<RenderResult, MfeError> {
        self.core
            .execute(MfeCapability::Render, context, |ctx| async move { self.hooks.do_render(&self.core, &ctx).await })
            .await
    }

    /// Data reload in place when state changes but this MFE stays selected.
    pub async fn refresh(&self, context: MfeContext) -> Result<(), MfeError> {
        self.core
            .execute(MfeCapability::Refresh, context, |ctx| async move { self.hooks.do_refresh(&self.core, &ctx).await })
            .await
    }

    /// Telemetry publication. Does not trigger registry re-evaluation.
    pub async fn emit(&self, context: MfeContext) -> Result<EmitResult, MfeError> {
        self.core
            .execute(MfeCapability::Emit, context, |ctx| async move { self.hooks.do_emit(&self.core, &ctx).await })
            .await
    }

    /// Execute a GraphQL query against this MFE without rendering.
    pub async fn query(&self, context: MfeContext) -> Result<QueryResult, MfeError> {
        self.core
            .execute(MfeCapability::Query, context, |ctx| async move { self.hooks.do_query(&self.core, &ctx).await })
            .await
    }

    /// GraphQL SDL introspection for registry schema federation.
    pub async fn schema(&self, context: MfeContext) -> Result<SchemaResult, MfeError> {
        self.core
            .execute(MfeCapability::Schema, context, |ctx| async move { self.hooks.do_schema(&self.core, &ctx).await })
            .await
    }

    /// JWT validation — the gate check the daemon runs before render().
    pub async fn authorize_access(&self, context: MfeContext) -> Result<bool, MfeError> {
        self.core
            .execute(MfeCapability::AuthorizeAccess, context, |ctx| async move { self.hooks.do_authorize_access(&self.core, &ctx).await })
            .await
    }

    /// Liveness and dependency checks for registry polling.
    pub async fn health(&self, context: MfeContext) -> Result<HealthResult, MfeError> {
        self.core
            .execute(MfeCapability::Health, context, |ctx| async move { self.hooks.do_health(&self.core, &ctx).await })
            .await
    }

    /// MFE-initiated push of domain state for registry re-evaluation.
    pub async fn update_control_plane_state(&self, context: MfeContext) -> Result<ControlPlaneStateResult, MfeError> {
        self.core
            .execute(MfeCapability::UpdateControlPlaneState, context, |ctx| async move { self.hooks.do_update_control_plane_state(&self.core, &ctx).await })
            .await
    }

}
